//! Storage profile manifest, generated by `scripts/oracle/build-fixtures.ts`
//! from a database written by the real WrongStack indexer.

use std::collections::BTreeMap;
use std::sync::OnceLock;

use serde::Deserialize;

const BASELINE_MANIFEST: &str =
    include_str!("../../../contracts/profiles/wrongstack-index-v5-baseline/manifest.json");

#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Column {
    pub name: String,
    #[serde(rename = "type")]
    pub decl_type: String,
    pub notnull: bool,
    pub default: Option<String>,
    pub pk: i64,
}

#[derive(Debug, Clone, Deserialize)]
pub struct IndexDef {
    pub name: String,
    pub table: String,
    pub sql: Option<String>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct VirtualTable {
    pub name: String,
    pub sql: String,
}

#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Profile {
    pub id: String,
    pub schema_version: i64,
    pub ddl_sha256: String,
    pub tables: BTreeMap<String, Vec<Column>>,
    pub optional_tables: BTreeMap<String, Option<Vec<Column>>>,
    pub virtual_tables: Vec<VirtualTable>,
    pub indexes: Vec<IndexDef>,
    pub metadata_keys: Vec<String>,
}

const BASELINE_SEMANTIC: &str =
    include_str!("../../../contracts/profiles/wrongstack-index-v5-baseline/semantic.json");

/// Semantic half of the profile (WI-007): version markers the baseline engine
/// writes and the fingerprint covering storage + semantics.
#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SemanticProfile {
    pub id: String,
    pub profile_fingerprint: String,
    pub storage_fingerprint: String,
    pub semantic_fingerprint: String,
    pub semantic: SemanticSection,
}

#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SemanticSection {
    pub version_markers: BTreeMap<String, String>,
}

pub fn baseline_semantic() -> &'static SemanticProfile {
    static SEMANTIC: OnceLock<SemanticProfile> = OnceLock::new();
    SEMANTIC.get_or_init(|| {
        serde_json::from_str(BASELINE_SEMANTIC).expect("embedded semantic profile is valid")
    })
}

/// The current WrongStack baseline profile (`SCHEMA_VERSION` 5).
pub fn baseline_profile() -> &'static Profile {
    static PROFILE: OnceLock<Profile> = OnceLock::new();
    PROFILE.get_or_init(|| {
        serde_json::from_str(BASELINE_MANIFEST).expect("embedded baseline manifest is valid")
    })
}

/// Columns WrongStack's `repairMissingColumns` adds with `ALTER TABLE` when an
/// older database lacks them (writer-init.ts). A missing column outside this
/// list cannot be repaired by the baseline initializer.
pub const REPAIRABLE_COLUMNS: &[(&str, &str)] = &[
    ("files", "package"),
    ("files", "content_hash"),
    ("files", "git_blob"),
    ("symbols", "end_line"),
    ("symbols", "is_exported"),
    ("symbols", "signature_hash"),
    ("refs", "lang"),
    ("refs", "module"),
    ("refs", "to_file"),
    ("file_concepts", "signature_hash"),
];

/// Tables `initIndexSchema` creates additively with `IF NOT EXISTS`; their
/// absence means an older (repairable) database, not a divergent one.
pub const ADDITIVE_TABLES: &[&str] = &[
    "lang_family",
    "symbol_rank",
    "file_rank",
    "file_concepts",
    "subsystems",
    "concept_edges",
    "file_vectors",
];

/// Deprecated column dropped on open (`dropDeprecatedSymbolsColumns`).
pub const DEPRECATED_COLUMNS: &[(&str, &str)] = &[("symbols", "text")];

/// FTS5 shadow tables owned by SQLite for `symbols_fts`.
pub fn is_fts_shadow(name: &str) -> bool {
    matches!(
        name,
        "symbols_fts_config"
            | "symbols_fts_content"
            | "symbols_fts_data"
            | "symbols_fts_docsize"
            | "symbols_fts_idx"
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn embedded_manifest_parses_and_has_core_tables() {
        let p = baseline_profile();
        assert_eq!(p.id, wrongindex_contracts::BASELINE_PROFILE_ID);
        assert_eq!(p.schema_version, 5);
        for t in ["metadata", "files", "symbols", "refs", "lang_family"] {
            assert!(p.tables.contains_key(t), "missing {t}");
        }
        assert!(p.optional_tables.contains_key("symbol_vectors"));
        assert!(p.metadata_keys.iter().any(|k| k == "next_symbol_id"));
    }

    #[test]
    fn semantic_profile_matches_storage_profile() {
        let s = baseline_semantic();
        assert_eq!(s.id, baseline_profile().id);
        assert_eq!(s.profile_fingerprint.len(), 64);
        assert_eq!(
            s.semantic
                .version_markers
                .get("version")
                .map(String::as_str),
            Some("5")
        );
        assert_eq!(
            s.semantic
                .version_markers
                .get("relation_graph_version")
                .map(String::as_str),
            Some("2")
        );
    }

    #[test]
    fn repairable_columns_exist_in_profile() {
        let p = baseline_profile();
        for (table, column) in REPAIRABLE_COLUMNS {
            let cols = p.tables.get(*table).expect("table in profile");
            assert!(cols.iter().any(|c| c.name == *column), "{table}.{column}");
        }
    }
}
